import React, { createContext, useState, useContext, useEffect } from 'react';

// Create context
const DevNoticeContext = createContext();

// Provider component
export const DevNoticeProvider = ({ children }) => {
  const [showDevNotice, setShowDevNotice] = useState(false);

  // Periksa localStorage saat komponen dimount
  useEffect(() => {
    // Hapus item ini jika ingin modal selalu muncul untuk testing
    localStorage.removeItem('devNoticeAcknowledged');
    
    const hasAcknowledged = localStorage.getItem('devNoticeAcknowledged');
    
    if (!hasAcknowledged) {
      // Jika belum pernah acknowledge, tampilkan modal
      setShowDevNotice(true);
      document.body.classList.add('modal-open');
      document.getElementById('root')?.classList.add('blur-background');
    } else if (hasAcknowledged !== 'permanent') {
      // Periksa timestamp untuk pengingat mingguan
      const acknowledgedTime = parseInt(hasAcknowledged, 10);
      const oneWeek = 7 * 24 * 60 * 60 * 1000; // 7 hari dalam milidetik
      
      if (Date.now() - acknowledgedTime > oneWeek) {
        setShowDevNotice(true);
        document.body.classList.add('modal-open');
        document.getElementById('root')?.classList.add('blur-background');
      }
    }
  }, []);

  // Handler untuk menutup modal
  const handleCloseDevNotice = (dontShowAgain) => {
    setShowDevNotice(false);
    document.body.classList.remove('modal-open');
    document.getElementById('root')?.classList.remove('blur-background');
    
    if (dontShowAgain) {
      } else {
      localStorage.setItem('devNoticeAcknowledged', Date.now().toString());
    }
  };

  return (
    <DevNoticeContext.Provider value={{ showDevNotice, handleCloseDevNotice }}>
      {children}
    </DevNoticeContext.Provider>
  );
};

// Custom hook untuk menggunakan context
export const useDevNotice = () => {
  const context = useContext(DevNoticeContext);
  if (!context) {
    throw new Error('useDevNotice harus digunakan dalam DevNoticeProvider');
  }
  return context;
};
